/**
 * Shared fixture battery + serialization for the Ω-constraints parity golden.
 *
 * The golden file (`omega-parity.golden.json`) is generated by
 * gen-omega-parity.ts and the parity test
 * (`omega-constraints.parity.test.ts`) re-runs these exact fixtures and
 * asserts byte-equality. Both import this module so the fixtures +
 * serialization are identical on both sides; only the code under test
 * (enumerateStates / clusterToFacets / the two solvers) moves underneath.
 *
 * Each fixture pins one Ω-interpretation rule from state-enumerator +
 * clusterToFacets: exhaustive/non-exhaustive/1-slot categoricals, k=1/k=3
 * thresholds, bundle fall-through, free questions, every hard/soft/self/
 * dangling edge type, the Ω-liveness unquoted demotion (facet only — the
 * V-rep enumeration ignores it), and a mixed cluster.
 */
import type { Platform } from '@arb/types';
import type { Cluster, MarketRef, QuestionNode, OutcomeSetRef, EdgeRef } from '../../graph/types.js';
import type { FacetConstraint } from '../types.js';
import type { WorldState } from '../../graph/types.js';
import { PriceCache } from '../../clob/price-cache.js';
import { enumerateStates } from '../state-enumerator.js';
import { clusterToFacets, buildFacetLP, solveFacetLP } from '../facet-lp.js';
import { buildLP } from '../lp-builder.js';
import { solveLP } from '../solver.js';
import { NO_EXECUTION_GATE } from '../types.js';

const PLAT: Platform = 'kalshi';

export interface ParityFixture {
  name: string;
  cluster: Cluster;
  price: PriceCache;
  /** Questions the facet demotion predicate treats as UNQUOTED (Ω-liveness L2). */
  unquoted: number[];
}

interface Builder {
  q: (qid: number, bid: number, ask: number) => void;
  questions: Map<number, QuestionNode>;
  marketIds: Set<number>;
  price: PriceCache;
}

function mkBuilder(): Builder {
  const questions = new Map<number, QuestionNode>();
  const marketIds = new Set<number>();
  const price = new PriceCache();
  const ts = Date.now();
  const q = (qid: number, bid: number, ask: number): void => {
    const node: QuestionNode = {
      questionId: qid, canonicalSubject: `q${qid}`, conditionShape: null,
      conditionValue: null, conditionDate: null, markets: new Map(),
    };
    const m: MarketRef = { marketId: qid, platform: PLAT, platformId: `m${qid}` };
    node.markets.set(qid, m);
    questions.set(qid, node);
    marketIds.add(qid);
    price.update({ marketId: qid, platform: PLAT, bestBid: bid, bestAsk: ask, bidSize: 200, askSize: 200, timestamp: ts } as any);
  };
  return { q, questions, marketIds, price };
}

function cluster(b: Builder, outcomeSets: OutcomeSetRef[], edges: EdgeRef[]): Cluster {
  return { id: 1, questions: b.questions, outcomeSets, edges, marketIds: b.marketIds, validStates: [], dirty: true };
}

const cat = (setId: number, slots: number[], isExhaustive: boolean): OutcomeSetRef =>
  ({ setId, setType: 'categorical', setName: `c${setId}`, slotQuestionIds: slots, isExhaustive });
const thr = (setId: number, slots: number[]): OutcomeSetRef =>
  ({ setId, setType: 'threshold_series', setName: `t${setId}`, slotQuestionIds: slots });
const bundle = (setId: number, slots: number[]): OutcomeSetRef =>
  ({ setId, setType: 'bundle', setName: `b${setId}`, slotQuestionIds: slots });
const edge = (id: number, a: number, c: number, t: string, det = true): EdgeRef =>
  ({ edgeId: id, antecedentQuestionId: a, consequentQuestionId: c, edgeType: t, confidence: 1, deterministic: det, basisRisk: null });

/** The deterministic fixture battery. Rebuilt fresh on each call (pure). */
export function buildFixtures(): ParityFixture[] {
  const out: ParityFixture[] = [];
  const add = (name: string, build: (b: Builder) => { sets: OutcomeSetRef[]; edges: EdgeRef[] }, unquoted: number[] = []) => {
    const b = mkBuilder();
    const { sets, edges } = build(b);
    out.push({ name, cluster: cluster(b, sets, edges), price: b.price, unquoted });
  };

  add('cat-exhaustive-k2', (b) => { b.q(1, 0.30, 0.33); b.q(2, 0.30, 0.33); return { sets: [cat(1, [1, 2], true)], edges: [] }; });
  add('cat-exhaustive-k3', (b) => { b.q(1, 0.28, 0.31); b.q(2, 0.28, 0.31); b.q(3, 0.28, 0.31); return { sets: [cat(1, [1, 2, 3], true)], edges: [] }; });
  add('cat-nonexhaustive-k3', (b) => { b.q(1, 0.28, 0.31); b.q(2, 0.28, 0.31); b.q(3, 0.28, 0.31); return { sets: [cat(1, [1, 2, 3], false)], edges: [] }; });
  add('cat-1slot', (b) => { b.q(1, 0.40, 0.44); return { sets: [cat(1, [1], true)], edges: [] }; });
  add('cat-b01-missing-slot', (b) => { b.q(1, 0.30, 0.33); b.q(2, 0.30, 0.33); return { sets: [cat(1, [1, 2, 999], true)], edges: [] }; });
  add('threshold-k1', (b) => { b.q(1, 0.40, 0.44); return { sets: [thr(1, [1])], edges: [] }; });
  add('threshold-k3', (b) => { b.q(1, 0.20, 0.24); b.q(2, 0.40, 0.44); b.q(3, 0.60, 0.64); return { sets: [thr(1, [1, 2, 3])], edges: [] }; });
  add('bundle-small', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [bundle(1, [1, 2])], edges: [] }; });
  add('free-3', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); b.q(3, 0.40, 0.44); return { sets: [], edges: [] }; });
  add('edge-strict_impl', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 2, 'strict_implication')] }; });
  add('edge-mutex', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 2, 'mutual_exclusion')] }; });
  add('edge-equivalence', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 2, 'equivalence')] }; });
  add('edge-soft', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 2, 'near_equivalence')] }; });
  add('edge-nondeterministic', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 2, 'strict_implication', false)] }; });
  add('edge-self', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 1, 'mutual_exclusion')] }; });
  add('edge-dangling', (b) => { b.q(1, 0.40, 0.44); b.q(2, 0.40, 0.44); return { sets: [], edges: [edge(1, 1, 3, 'equivalence')] }; });
  add('unquoted-demotion', (b) => { b.q(1, 0.28, 0.31); b.q(2, 0.28, 0.31); b.q(3, 0.28, 0.31); return { sets: [cat(1, [1, 2, 3], true)], edges: [] }; }, [1]);
  add('mixed', (b) => {
    b.q(1, 0.30, 0.33); b.q(2, 0.30, 0.33); b.q(3, 0.20, 0.24); b.q(4, 0.55, 0.59); b.q(5, 0.40, 0.44);
    return { sets: [cat(1, [1, 2], true), thr(2, [3, 4])], edges: [edge(1, 5, 1, 'strict_implication')] };
  });

  return out;
}

// ───────────────────────── deterministic serialization ─────────────────────────

/** One world state → `q1=0,q2=1,…` with qids ASCENDING. */
function stateKey(s: WorldState): string {
  return [...s.keys()].sort((a, b) => a - b).map((q) => `${q}=${s.get(q) ? 1 : 0}`).join(',');
}

/** enumerateStates output → SORTED array of state keys (order-independent). */
export function serializeStates(states: WorldState[]): string[] {
  return states.map(stateKey).sort();
}

/** clusterToFacets output → SORTED array of `coeff|rhs|kind` rows. */
export function serializeFacets(facets: FacetConstraint[]): string[] {
  return facets
    .map((f) => {
      const coeff = [...f.coeff].sort((a, b) => a[0] - b[0]).map(([q, c]) => `${q}:${c}`).join(';');
      return `${coeff}|${f.rhs}|${f.kind}`;
    })
    .sort();
}

/** Round an optimal cost to 9 dp (or null) so both sides go through identical
 *  rounding — the refactor reproduces the SAME LP string, hence the same cost. */
export function roundCost(n: number | null): number | null {
  return n == null || !Number.isFinite(n) ? n : Number(n.toFixed(9));
}

/** One serialized golden row per fixture. */
export interface ParityRow {
  name: string;
  states: string[];
  facets: string[];
  vCost: number | null;
  fCost: number | null;
}

/**
 * Compute the serialized parity row for one fixture — the SINGLE definition used by
 * BOTH the golden generator and the parity test. `vCost` is the V-rep optimal cost
 * (enumerateStates → buildLP → solveLP; null when the enumeration is empty / no LP);
 * `fCost` is the facet optimal cost (buildFacetLP → solveFacetLP; null when no leg is
 * usable). `facets` is captured with the fixture's explicit unquoted predicate so the
 * Ω-liveness L2 demotion row is pinned exactly.
 */
export async function computeRow(fix: ParityFixture): Promise<ParityRow> {
  const now = Date.now();
  const states = enumerateStates(fix.cluster, { maxStates: 100_000, clusterSizeCap: 1e9 });
  const facets = clusterToFacets(fix.cluster, (q) => fix.unquoted.includes(q));

  // V-rep cost: enumerate → buildLP → solveLP.
  fix.cluster.validStates = states;
  let vCost: number | null = null;
  const vlp = buildLP(fix.cluster, fix.price, NO_EXECUTION_GATE);
  if (vlp) {
    const vres = await solveLP(vlp);
    vCost = vres.status === 'Optimal' ? vres.optimalCost : null;
  }
  fix.cluster.validStates = []; // restore (facet needs no states)

  // Facet cost: buildFacetLP → solveFacetLP.
  let fCost: number | null = null;
  const flp = buildFacetLP(fix.cluster, fix.price, NO_EXECUTION_GATE, now);
  if (flp) {
    const fres = await solveFacetLP(flp);
    fCost = fres.status === 'Optimal' ? fres.optimalCost : null;
  }

  return {
    name: fix.name,
    states: serializeStates(states),
    facets: serializeFacets(facets),
    vCost: roundCost(vCost),
    fCost: roundCost(fCost),
  };
}
